(gen_random_uuid()::text,'mz','user','HCM-ADMIN-CONSOLE.schemas','{"title": "user", "$schema": "http://json-schema.org/draft-07/schema#", "properties": {"enumProperties": [{"enum": ["Temporary", "Permanent"], "name": "HCM_ADMIN_CONSOLE_USER_EMPLOYMENT_TYPE", "color": "#93c47d", "uniqueKey": "userEmployementType", "isRequired": true, "description": "Employement Type", "orderNumber": 4, "errorMessage": "Employment Type is missing or invalid.", "freezeColumnIfFilled": true}, {"enum": ["Active", "Inactive"], "name": "HCM_ADMIN_CONSOLE_USER_USAGE", "color": "#93c47d", "uniqueKey": "userUsage", "isRequired": true, "description": "User Usage", "orderNumber": 5, "errorMessage": "User usage is missing or invalid."}, {"enum": ["BANK", "MTN"], "name": "HCM_ADMIN_CONSOLE_USER_PAYMENT_PROVIDER", "color": "#93c47d", "uniqueKey": "userPaymentProvider", "isRequired": false, "description": "Payment Provider", "orderNumber": 9, "errorMessage": "Payment Provider must be BANK or MTN."}], "stringProperties": [{"name": "HCM_ADMIN_CONSOLE_USER_NAME", "type": "string", "color": "#93c47d", "pattern": "^[A-Za-z0-9 \\-]{2,128}$", "uniqueKey": "userPrefferedName", "isRequired": true, "description": "User Name", "orderNumber": 1, "errorMessage": "Name must be alphanumeric, can include spaces and hyphens, and be between 2 to 128 characters.", "freezeColumnIfFilled": true}, {"name": "HCM_ADMIN_CONSOLE_USER_PHONE_NUMBER", "type": "string", "color": "#93c47d", "pattern": "^[6-9][0-9]{9}$", "isUnique": true, "uniqueKey": "userPhoneNumber", "isRequired": true, "description": "Phone Number", "orderNumber": 2, "errorMessage": "Phone Number must be 10 digits.", "freezeColumnIfFilled": true}, {"name": "HCM_ADMIN_CONSOLE_USER_ROLE", "color": "#93c47d", "prefix": "ACCESSCONTROL_ROLES_ROLES_", "uniqueKey": "userRoles", "hideColumn": true, "description": "User Role", "orderNumber": 3, "errorMessage": "At least one user role is required.", "freezeTillData": true, "multiSelectDetails": {"enum": ["DISTRIBUTOR", "HEALTH_FACILITY_WORKER", "WAREHOUSE_MANAGER", "NATIONAL_SUPERVISOR", "DISTRICT_SUPERVISOR", "TEAM_SUPERVISOR", "PROVINCIAL_SUPERVISOR", "DASHBOARD_VIEWER", "PROXIMITY_SUPERVISOR", "CAMPAIGN_SUPERVISOR", "PAYMENT_EDITOR", "PAYMENT_REVIEWER", "PAYMENT_APPROVER", "FIELD_SUPPORT"], "maxSelections": 5, "minSelections": 1}, "freezeColumnIfFilled": true}, {"name": "HCM_ADMIN_CONSOLE_BOUNDARY_CODE_MANDATORY", "type": "string", "color": "#93c47d", "uniqueKey": "boundaryCodes", "isRequired": true, "description": "Boundary Code (Mandatory)", "orderNumber": 6, "errorMessage": "Boundary Code is required and must be a valid string."}, {"name": "HCM_ADMIN_CONSOLE_USER_WORKER_ID", "type": "string", "color": "#93c47d", "isUpdate": false, "uniqueKey": "userWorkerId", "hideColumn": false, "description": "Worker Registry ID", "orderNumber": 8, "freezeColumn": true}, {"name": "HCM_ADMIN_CONSOLE_USER_PAYEE_PHONE_NUMBER", "type": "string", "color": "#93c47d", "uniqueKey": "userPayeePhoneNumber", "isRequired": false, "requiredIf": {"column": "HCM_ADMIN_CONSOLE_USER_PAYMENT_PROVIDER", "values": ["MTN"]}, "description": "Payee Phone Number", "orderNumber": 10, "errorMessage": "Payee Phone Number must be a valid string."}, {"name": "HCM_ADMIN_CONSOLE_USER_PAYEE_NAME", "type": "string", "color": "#93c47d", "pattern": "^[A-Za-z0-9 ]{1,100}$", "maxLength": 100, "uniqueKey": "userPayeeName", "isRequired": false, "requiredIf": {"column": "HCM_ADMIN_CONSOLE_USER_PAYMENT_PROVIDER", "values": ["BANK", "MTN"]}, "description": "Payee Name", "orderNumber": 11, "errorMessage": "Payee Name must be alphanumeric (spaces allowed) and max 100 characters."}, {"name": "HCM_ADMIN_CONSOLE_USER_BANK_ACCOUNT", "type": "string", "color": "#93c47d", "pattern": "^[0-9]{10}$", "uniqueKey": "userBankAccount", "isRequired": false, "requiredIf": {"column": "HCM_ADMIN_CONSOLE_USER_PAYMENT_PROVIDER", "values": ["BANK"]}, "description": "Bank Account", "orderNumber": 12, "errorMessage": "Bank Account must be exactly 10 dig